use std::{fs,path::Path};use serde_json::{Value,json};use sha2::{Digest,Sha256};
fn main(){let r=Path::new("/home/ubuntu/src/zopro-perf-work/g2-part-ready175");let archive=r.join("initial-build");fs::create_dir(&archive).unwrap();fs::rename(r.join("native"),archive.join("native")).unwrap();for f in ["build-plan.json","build-pins.json","source-audit.json"]{fs::copy(r.join(f),archive.join(f)).unwrap();}
let parent=r.join("source/crates/zopro-core/src/msm_affine/g2_phi.rs");let child=r.join("source/crates/zopro-core/src/msm_affine/g2_phi/part_ready.rs");fs::copy(&parent,archive.join("g2_phi.rs")).unwrap();fs::copy(&child,archive.join("part_ready.rs")).unwrap();let p=fs::read_to_string(&parent).unwrap();let prefix="#[cfg(zopro_phi_part_ready)]\nmod part_ready;\n";let s=p.strip_prefix(prefix).unwrap().replacen("use super::{",&format!("{prefix}use super::{{"),1);fs::write(&parent,s).unwrap();
let old=fs::read_to_string(&child).unwrap();let new=old.replace("std::panic::catch_unwind(|| {","std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {").replace("                });\n                assert!(result.is_err());","                }));\n                assert!(result.is_err());");assert_ne!(old,new);fs::write(&child,&new).unwrap();fs::write(r.join("part_ready.rs"),new).unwrap();
let auditpath=r.join("source-audit.json");let mut a:Value=serde_json::from_slice(&fs::read(&auditpath).unwrap()).unwrap();a["module_declaration"] = json!(prefix);a["module_declaration_location"]=json!("after inner documentation, before first use");a["compilation_repair"]=json!({"initial_sdk_calls":0,"initial_tests_executed":0,"reason":"E0753 module declaration before inner docs; E0277 panic test wrapper on ThreadPool","source":"repair.rs","algorithm_changed":false});fs::write(&auditpath,serde_json::to_vec_pretty(&a).unwrap()).unwrap();
let pinpath=r.join("build-pins.json");let mut pins:Value=serde_json::from_slice(&fs::read(&pinpath).unwrap()).unwrap();for p in [parent,child,auditpath,r.join("part_ready.rs"),r.join("repair.rs")]{pins[p.display().to_string()]=json!(format!("{:x}",Sha256::digest(fs::read(&p).unwrap())));}fs::write(pinpath,serde_json::to_vec_pretty(&pins).unwrap()).unwrap();}
